using Educatinal_Platform.DTOs;
using Educatinal_Platform.Models;
using Educatinal_Platform.Repositories;

namespace Educatinal_Platform.Services;

public interface ISiteSettingsService { Task<SiteSettingsDto> GetAsync(); Task<SiteSettingsDto> UpdateAsync(SiteSettingsDto dto); }
public class SiteSettingsService(ISiteSettingsRepository repository) : ISiteSettingsService
{
    private static readonly HashSet<string> SocialKeys = ["linkedin", "facebook", "instagram", "youtube", "tiktok", "x", "whatsapp", "telegram"];
    private static readonly HashSet<string> NavigationKeys = ["home", "courses", "categories", "about", "login", "register"];
    private static readonly HashSet<string> AllowedPaths = ["/", "/courses", "/about", "/login", "/register"];
    public async Task<SiteSettingsDto> GetAsync() => ToDto(await repository.GetAsync());
    public async Task<SiteSettingsDto> UpdateAsync(SiteSettingsDto dto)
    {
        if (string.IsNullOrWhiteSpace(dto.PlatformName) || dto.PlatformName.Trim().Length > 80 || dto.AboutTitle?.Trim().Length > 160 || dto.AboutContent?.Length > 5000 || dto.WhoWeAreTitleEn?.Trim().Length > 160 || dto.WhoWeAreTitleAr?.Trim().Length > 160 || dto.WhoWeAreContentEn?.Length > 5000 || dto.WhoWeAreContentAr?.Length > 5000 || dto.ConsultationDescriptionEn?.Length > 5000 || dto.ConsultationDescriptionAr?.Length > 5000) throw new ArgumentException("Site settings are invalid.");
        var social = dto.SocialLinks.Where(item => SocialKeys.Contains(item.Key) && IsValidExternalUrl(item.Value)).ToDictionary(item => item.Key, item => item.Value.Trim());
        if (dto.SocialLinks.Any(item => SocialKeys.Contains(item.Key) && !string.IsNullOrWhiteSpace(item.Value) && !IsValidExternalUrl(item.Value))) throw new ArgumentException("Social links must be valid HTTPS URLs.");
        var visibility = dto.SocialLinkVisibility.Where(item => SocialKeys.Contains(item.Key)).ToDictionary(item => item.Key, item => item.Value);
        var navigation = dto.NavigationLinks.Where(item => NavigationKeys.Contains(item.Key) && AllowedPaths.Contains(item.Value)).ToDictionary(item => item.Key, item => item.Value);
        if (dto.NavigationLinks.Any(item => NavigationKeys.Contains(item.Key) && !AllowedPaths.Contains(item.Value))) throw new ArgumentException("Navigation links must use an approved internal route.");
        var labels = dto.NavigationLabels.Where(item => NavigationKeys.Contains(item.Key) && !string.IsNullOrWhiteSpace(item.Value) && item.Value.Trim().Length <= 40).ToDictionary(item => item.Key, item => item.Value.Trim());
        if (dto.BioStats.Any(stat => !IsValidBioStat(stat))) throw new ArgumentException("Bio statistics are invalid.");
        var settings = await repository.GetAsync(); settings.PlatformName = dto.PlatformName.Trim(); settings.AboutTitle = string.IsNullOrWhiteSpace(dto.AboutTitle) ? settings.AboutTitle : dto.AboutTitle.Trim(); settings.AboutContent = string.IsNullOrWhiteSpace(dto.AboutContent) ? settings.AboutContent : dto.AboutContent.Trim(); settings.AboutTitleEn = Trim(dto.AboutTitleEn, 160); settings.AboutTitleAr = Trim(dto.AboutTitleAr, 160); settings.AboutContentEn = Trim(dto.AboutContentEn, 5000); settings.AboutContentAr = Trim(dto.AboutContentAr, 5000); settings.IsAboutVisible = dto.IsAboutVisible; settings.WhoWeAreTitleEn = Trim(dto.WhoWeAreTitleEn, 160); settings.WhoWeAreTitleAr = Trim(dto.WhoWeAreTitleAr, 160); settings.WhoWeAreContentEn = Trim(dto.WhoWeAreContentEn, 5000); settings.WhoWeAreContentAr = Trim(dto.WhoWeAreContentAr, 5000); settings.IsWhoWeAreVisible = dto.IsWhoWeAreVisible; settings.SocialLinks = social; settings.SocialLinkVisibility = visibility; settings.NavigationLinks = navigation; settings.NavigationLabels = labels; settings.BioTitleEn = Trim(dto.BioTitleEn, 160); settings.BioTitleAr = Trim(dto.BioTitleAr, 160); settings.BioDescriptionEn = Trim(dto.BioDescriptionEn, 5000); settings.BioDescriptionAr = Trim(dto.BioDescriptionAr, 5000); settings.ConsultationDescriptionEn = Trim(dto.ConsultationDescriptionEn, 5000); settings.ConsultationDescriptionAr = Trim(dto.ConsultationDescriptionAr, 5000); settings.BioStats = dto.BioStats.Select(stat => new BioStat { Id = string.IsNullOrWhiteSpace(stat.Id) ? Guid.NewGuid().ToString("N") : stat.Id, Icon = stat.Icon.Trim().ToLowerInvariant(), Count = stat.Count.Trim(), LabelEn = stat.LabelEn.Trim(), LabelAr = stat.LabelAr.Trim(), Url = stat.Url.Trim(), IsVisible = stat.IsVisible }).ToList();
        await repository.SaveAsync(settings); return ToDto(settings);
    }
    private static bool IsValidExternalUrl(string value) => Uri.TryCreate(value, UriKind.Absolute, out var uri) && uri.Scheme == Uri.UriSchemeHttps;
    private static string Trim(string? value, int max) => (value ?? "").Trim()[..Math.Min((value ?? "").Trim().Length, max)];
    private static bool IsValidBioStat(BioStatDto stat) => new[] { "linkedin", "youtube", "facebook", "instagram", "tiktok", "x", "whatsapp", "telegram", "chart" }.Contains(stat.Icon?.Trim().ToLowerInvariant()) && stat.Count?.Trim().Length is > 0 and <= 40 && stat.LabelEn?.Trim().Length <= 100 && stat.LabelAr?.Trim().Length <= 100 && IsValidExternalUrl(stat.Url);
    private static SiteSettingsDto ToDto(SiteSettings item) => new() { PlatformName = item.PlatformName, AboutTitle = item.AboutTitle, AboutContent = item.AboutContent, AboutTitleEn = item.AboutTitleEn, AboutTitleAr = item.AboutTitleAr, AboutContentEn = item.AboutContentEn, AboutContentAr = item.AboutContentAr, IsAboutVisible = item.IsAboutVisible, WhoWeAreTitleEn = item.WhoWeAreTitleEn, WhoWeAreTitleAr = item.WhoWeAreTitleAr, WhoWeAreContentEn = item.WhoWeAreContentEn, WhoWeAreContentAr = item.WhoWeAreContentAr, IsWhoWeAreVisible = item.IsWhoWeAreVisible, BioTitleEn = item.BioTitleEn, BioTitleAr = item.BioTitleAr, BioDescriptionEn = item.BioDescriptionEn, BioDescriptionAr = item.BioDescriptionAr, ConsultationDescriptionEn = item.ConsultationDescriptionEn, ConsultationDescriptionAr = item.ConsultationDescriptionAr, BioStats = item.BioStats.Select(stat => new BioStatDto { Id = string.IsNullOrWhiteSpace(stat.Id) ? Guid.NewGuid().ToString("N") : stat.Id, Icon = stat.Icon, Count = stat.Count, LabelEn = stat.LabelEn, LabelAr = stat.LabelAr, Url = stat.Url, IsVisible = stat.IsVisible }).ToList(), SocialLinks = item.SocialLinks, SocialLinkVisibility = item.SocialLinkVisibility, NavigationLinks = item.NavigationLinks, NavigationLabels = item.NavigationLabels };
}
